Section CANSEC1. Context {rc : runConstT}.
Section X4F.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT lo : Z) (src : list Z) (cells : list deltX1) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x1_table_ok cells 11.
  Hypothesis ECB : cbs = firstn 4096 (x1_bytes' cells).
  Hypothesis LCB : zlen cbs = 4096.
  Hypothesis D8 : 8 <= DST.
  Hypothesis DC : 0 < dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 4096 <= lo.
  Hypothesis DJ1 : DT + 4 + 4096 <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation DW := [(SP - 4096, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  (* [comment removed for export] *)
  Definition X4M (mm : fmem) (sps ws : list word) : Prop :=
    (exists buf, u8arr psegs mm DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap)
    /\ bytes_at psegs mm SS (map (Z_to_bv 8) src)
    /\ bytes_at psegs mm (DT + 4) cbs
    /\ stk psegs mm lo (SP + -416)
    /\ (exists j0, rw_cells psegs mm (SP + -416) [CB 88 j0])
    /\ u64arr psegs mm (SP + -328) sps /\ length sps = 9%nat
    /\ u64arr psegs mm (SP + -256) ws /\ length ws = 19%nat
    /\ rw_cells psegs mm (SP + -104) FRS
    /\ mem_inv psegs mm /\ munch DW m0 mm /\ wmono psegs m0 mm.

  (* [comment removed for export] *)
  Lemma x4_epi : forall mm (t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6 xra : word),
    stk psegs mm lo (SP + -104) -> rw_cells psegs mm (SP + -104) FRS ->
    mem_inv psegs mm -> munch DW m0 mm -> wmono psegs m0 mm ->
    evt psegs POST (MS (mkR xra (Z_to_bv 64 (SP + -416)) gp tp t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7
                           x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6) F (Z_to_bv 64 0x19e5c) fc None mm (seg_rom psegs)).
Proof using All.
