  (* [comment removed for export] *)
  Ltac x4pack OUT LB :=
    split; [eexists; split; [exact OUT| rewrite ?Zupd_length; exact LB]|];
    split; [eassumption|]; split; [eassumption|]; split; [eassumption|];
    split; [eexists; eassumption|];
    repeat (split; [eassumption|]); eassumption.

  (* [comment removed for export] *)
  Section STREAM.
  Variables (k SE OPk SEG DBC : Z) (sps ws : list word).
  Hypothesis K4 : 0 <= k < 4.
  Hypothesis HSE : DST <= OPk <= SE.
  Hypothesis HSE2 : SE <= DST + dcap.
  Hypothesis WOP : nth_error ws (Z.to_nat (4 + k)) = Some (Z_to_bv 64 OPk).

  (* [comment removed for export] *)
  Notation ST pc mm t6w a1 a2 a3 x9 x18 x19 x20 x21 x24 x25 x26 :=
    (MS (mkR (Z_to_bv 64 DST) (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 SEG) (Z_to_bv 64 (SP + -256)) (Z_to_bv 64 4)
             (Z_to_bv 64 (SE - OPk)) x9 (Z_to_bv 64 (DT + 4)) a1 a2 a3 (Z_to_bv 64 66832) (Z_to_bv 64 k)
             (Z_to_bv 64 (SP + -136)) (Z_to_bv 64 DBC) x18 x19 x20 x21 (Z_to_bv 64 SS) (Z_to_bv 64 (SS + 8)) x24 x25 x26
             (Z_to_bv 64 dcap) (Z_to_bv 64 64) (Z_to_bv 64 SE) (Z_to_bv 64 (SP + -224 + 8 * k)) t6w)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Hypothesis CONT : forall mm (a1 a2 a3 x9 x18 x19 x20 x21 x24 x25 x26 : word),
    X4M mm sps ws -> evt psegs POST (ST 0x19094 mm (Z_to_bv 64 OPk) a1 a2 a3 x9 x18 x19 x20 x21 x24 x25 x26).

  (* [comment removed for export] *)
  Lemma x4f_tail : forall (cnt : nat) q mm (a1 a2 a3 x9 x18 x19 x21 x24 x25 x26 : word),
    X4M mm sps ws -> OPk <= DST + q -> DST + q + Z.of_nat cnt = SE -> (0 < cnt)%nat ->
    evt psegs POST (ST 0x19064 mm (Z_to_bv 64 OPk) a1 a2 a3 x9 x18 x19 (Z_to_bv 64 (DST + q)) x21 x24 x25 x26).
