  Ltac x4dec ARR i last :=
    zstep; zstep; zstep;
    lazymatch goal with |- context [Z.land (?X ≫ 52) 18446744073709551614] =>
      let v := fresh "v" in let EV := fresh "EV" in let VR := fresh "VR" in
      rewrite (land_m2_shr X) by (apply Z.mod_pos_bound; lia);
      pose proof (shr53_bound X ltac:(apply Z.mod_pos_bound; lia)) as VR;
      remember (X ≫ 53) as v eqn:EV; clear EV;
      zstep;
      lazymatch goal with CE : bytes_at psegs ?mm (DT + 4) cbs |- _ =>
        let RC0 := fresh "RC" in let RC1 := fresh "RC" in
        destruct (x1_cell_rd psegs mm (DT + 4) cells 4096 v ltac:(rewrite <- ECB; exact CE) ltac:(lia) ltac:(lia) ltac:(lia))
          as [RC0 RC1];
        let NBc := fresh "NB" in let BYc := fresh "BY" in
        lazymatch goal with TCK : forall i, 0 <= i < 2^11 -> _ |- _ =>
          destruct (TCK v ltac:(change (2^11) with 2048; lia)) as (NBc & BYc) end;
        let c := fresh "c" in set (c := nth (Z.to_nat v) cells x1_default) in *;
        zstep; zstep; clear RC0 RC1;
        rewrite ?(byte_lit (x1_nbBits c)) by lia;
        zstep;
        (lazymatch last with true => zstep | false => idtac end);
        u8_sok ARR i; zstep; u8_store ARR i (x1_byte c); [rewrite byte_lit by lia; reflexivity|];
        clearbody c
      end
    end.

