    (forall q' pt' bits' mm' (a2' x18' x19' x20' x24' x25' x26' : word),
       X4M mm' sps ws -> DST + q + 4 <= DST + q' <= SE -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= n) -> 0 <= bits' <= 64 ->
       evt psegs POST (ST 0x18e1c mm' (Z_to_bv 64 OPk) (Z_to_bv 64 (DST + q')) a2' (Z_to_bv 64 (SE - 3)) (Z_to_bv 64 (SS + pt'))
